site.cssText:
/* ZONA-40 — local site stylesheet
   Self-contained for GitHub Pages. No Wikidot/Sigma dependency. */

:root{
  --bg:#f2f2f2;
  --paper:#fff;
  --ink:#222;
  --muted:#6d6d6d;
  --line:#c8c8c8;
  --soft:#f7f7f7;
  --black:#202020;
  --red:#901c1c;
  --red-dark:#681313;
  --mono:"Roboto Mono","Courier New",monospace;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif;line-height:1.55}
a{color:#7f1717;text-decoration:none}
a:hover{text-decoration:underline}
.site{max-width:1200px;margin:0 auto;background:var(--paper);min-height:100vh;box-shadow:0 0 22px rgba(0,0,0,.08)}
.site-header{background:#fff;border-bottom:4px solid var(--red)}
.header-inner{min-height:110px;max-width:1140px;margin:0 auto;padding:22px 25px;display:flex;align-items:center;justify-content:space-between;gap:25px}
.site-brand{display:flex;align-items:center;gap:14px;color:#222;text-decoration:none;min-width:0}
.site-brand:hover{text-decoration:none}
.scp-mark{width:58px;height:58px;border:3px solid #222;border-radius:50%;display:grid;place-items:center;position:relative;flex:0 0 auto}
.scp-mark:before,.scp-mark:after{content:"";position:absolute;background:#222}
.scp-mark:before{width:3px;height:76px;transform:rotate(60deg)}
.scp-mark:after{width:3px;height:76px;transform:rotate(-60deg)}
.scp-mark-center{position:relative;z-index:2;background:#fff;padding:3px;font:bold 11px var(--mono)}
.brand-copy{display:flex;flex-direction:column;min-width:0}
.brand-title{font:700 30px var(--mono);letter-spacing:-1px;line-height:1.1}
.brand-subtitle{font:700 10px Arial,sans-serif;letter-spacing:1.2px;color:#777;margin-top:5px}
.site-search{display:flex;gap:5px}
.site-search input{width:250px;height:32px;border:1px solid #aaa;padding:5px 9px;background:#fff;color:#222}
.site-search button{height:32px;background:var(--red);color:#fff;border:0;padding:0 12px;cursor:pointer}
.site-search button:hover{background:var(--red-dark)}
.mobile-menu{display:none;background:#222;color:#fff;border:0;padding:8px 10px;cursor:pointer}
.site-topbar{background:#222;border-bottom:3px solid var(--red)}
.topbar-inner{display:flex;max-width:1140px;margin:auto;overflow:auto}
.topbar-inner a{color:#fff;padding:10px 15px;font-size:12px;white-space:nowrap}
.topbar-inner a:hover{background:var(--red);text-decoration:none}
.site-layout{display:grid;grid-template-columns:225px minmax(0,1fr);min-height:calc(100vh - 150px)}
.site-sidebar{background:#f7f7f7;border-right:1px solid #ccc;padding:20px 12px}
.sidebar-box{border:1px solid #ccc;margin-bottom:15px;background:#fff}
.sidebar-heading{background:var(--red);color:#fff;padding:8px 10px;font-weight:bold;font-size:12px}
.site-sidebar a{display:block;padding:7px 9px;border-bottom:1px solid #ddd;font-size:12px;color:#333}
.site-sidebar a:last-child{border-bottom:0}
.site-sidebar a:hover{background:#eee;text-decoration:none;color:#7f1717}
.sidebar-text{padding:6px 9px;color:#555;font-size:12px}
.sidebar-text.mono,.mono{font-family:var(--mono)}
.site-main{padding:25px 38px 55px;min-width:0}
.breadcrumbs{color:#777;font-size:12px;margin:0 0 22px}
.classification{display:flex;justify-content:space-between;gap:20px;background:#eee;border-left:5px solid var(--red);padding:10px 13px;margin-bottom:22px;font-size:11px}
.classification strong{font-family:var(--mono)}
.classification span{color:#666}
.document-title{border-bottom:2px solid #222;padding-bottom:15px}
.eyebrow{font:bold 10px var(--mono);letter-spacing:1px;color:#777;margin-bottom:5px}
.document-title h1{margin:0 0 8px;font:700 36px var(--mono);line-height:1.2}
.document-title p{margin:0 0 12px;color:#555}
.document-title code{font:11px var(--mono);color:#555}
.document-meta{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0}
.document-meta>div{border:1px solid #bbb;background:#f5f5f5}
.document-meta span{display:block;padding:7px;border-bottom:1px solid #ccc;font-size:10px;font-weight:bold;color:#666}
.document-meta strong{display:block;padding:9px;font:12px var(--mono)}
.doc-section{margin-top:28px}
.doc-section h2{font:700 22px var(--mono);border-bottom:1px solid #aaa;padding-bottom:7px;margin:0 0 15px}
.doc-section h3{font-size:15px;margin:0 0 7px}
.doc-section p{margin:10px 0}
.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:18px 0}
.doc-block{border:1px solid #bbb;background:#fafafa;padding:16px}
.doc-block h3{font-family:var(--mono)}
.doc-block p:last-child{margin-bottom:0}
.warning{background:#eee;border-left:5px solid var(--red);padding:12px 15px;margin:20px 0}
.terminal,.code-block{background:#222;color:#ddd;border:1px solid #111;padding:13px;overflow:auto}
.terminal{font:12px/1.7 var(--mono);white-space:pre-wrap}
.site-main hr{border:0;border-top:1px solid #bbb;margin:35px 0}
.site-footer{text-align:center;border-top:2px solid #222;margin-top:45px;padding:25px;color:#666}
.site-footer strong{display:block;font:700 13px var(--mono);color:#444}
.site-footer small{display:block;margin-top:5px}
.search-hit{background:#fff0a8;outline:2px solid #e0c400}
@media(max-width:800px){
  .header-inner{min-height:85px;padding:15px}
  .site-search{display:none}
  .mobile-menu{display:block}
  .brand-title{font-size:24px}
  .brand-subtitle{font-size:8px;letter-spacing:.7px}
  .scp-mark{width:48px;height:48px}
  .site-layout{grid-template-columns:1fr}
  .site-sidebar{border-right:0;border-bottom:1px solid #ccc;padding:10px 15px}
  .site-sidebar.open{display:block}
  .site-main{padding:20px 15px 45px}
  .document-title h1{font-size:29px}
  .classification{display:block}
  .classification span{display:block;margin-top:5px}
  .document-meta,.columns{grid-template-columns:1fr}
  .topbar-inner a{padding:9px 11px;font-size:11px}
}


/* LORE MANAGER v6 image layout */
.lore-image{display:block;padding:0;margin-top:0;margin-bottom:14px}.lore-image img{border:1px solid var(--line);box-shadow:0 1px 4px rgba(0,0,0,.12)}.lore-image figcaption{font-size:11px;line-height:1.4;color:var(--muted);padding-top:6px}.back-link{display:inline-block;border:1px solid var(--line);background:var(--soft);padding:7px 11px;margin-bottom:8px}.back-link:hover{background:#eee;text-decoration:none}

.archive-category-head{display:flex;align-items:end;justify-content:space-between;gap:15px;border-bottom:1px solid #aaa;padding-bottom:7px}.archive-category-head h2{margin:0;border:0;padding:0}.archive-category-head h2 a{color:inherit}.archive-count{font-size:11px;color:#777;white-space:nowrap;margin-bottom:4px}.archive-cards{gap:12px}.archive-card{padding:20px;min-height:120px}.archive-card h3{font-size:19px}.archive-card p{font-size:11px;color:#777}.license-footer{max-width:900px;margin:10px auto 0;font-size:11px;line-height:1.5;color:#777}.lore-module{margin:18px 0}.lore-module.warning{background:#eee;border-left:5px solid var(--red);padding:12px 15px}.lore-module.quote{border-left:4px solid var(--red);padding:10px 15px;background:#f5f5f5}.lore-module.code{background:#222;color:#ddd;padding:13px;font-family:var(--mono);white-space:pre-wrap}.lore-module.callout{border:1px solid #bbb;background:#fafafa;padding:14px}.lore-module.keyvalue{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.lore-module.keyvalue>div{border:1px solid #ccc;background:#f7f7f7;padding:8px}.lore-module.keyvalue strong{display:block;font:11px var(--mono);color:#666;margin-bottom:4px}.lore-module table{width:100%;border-collapse:collapse}.lore-module th,.lore-module td{border:1px solid #bbb;padding:7px;text-align:left}.lore-module th{background:#eee}

/* v8 */
.custom-fields{} .document-meta{grid-template-columns:repeat(auto-fit,minmax(160px,1fr))}.lore-image{box-sizing:border-box}.lore-image figcaption{font-size:11px;color:#666;text-align:center;margin-top:6px;line-height:1.35}.rich-content .lore-module{margin:20px 0}.rich-content .lore-module.warning{background:#eee;border-left:5px solid var(--red);padding:12px 15px}.rich-content .lore-module.quote{border-left:4px solid var(--red);padding:10px 15px;background:#f5f5f5}.rich-content .lore-module.code{background:#222;color:#ddd;padding:13px;font-family:var(--mono);white-space:pre-wrap}.rich-content .lore-module.callout{border:1px solid #bbb;background:#fafafa;padding:14px}.rich-content .lore-module.keyvalue{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:7px}.rich-content .lore-module.keyvalue>div{border:1px solid #ccc;background:#f7f7f7;padding:8px}.rich-content .lore-module.keyvalue strong{display:block;font:11px var(--mono);color:#666;margin-bottom:4px}.rich-content .lore-module table{width:100%;border-collapse:collapse}.rich-content .lore-module th,.rich-content .lore-module td{border:1px solid #bbb;padding:7px;text-align:left}.rich-content .lore-module th{background:#eee}
